package com.gymmind.workout.api;
import com.gymmind.shared.api.ApiResponse; import com.gymmind.shared.security.*; import com.gymmind.workout.application.*; import org.springframework.web.bind.annotation.*; import java.time.LocalDate;
@RestController @RequestMapping("/api/v1/training") public class TrainingController { private final TrainingOverviewService service; private final CurrentActorProvider actors; public TrainingController(TrainingOverviewService s,CurrentActorProvider a){service=s;actors=a;} @GetMapping("/overview") public ApiResponse<TrainingOverviewView> overview(@RequestParam(required=false) LocalDate since,@RequestParam(required=false) LocalDate until,@RequestParam(required=false) Long memberId){return ApiResponse.success(service.overview(actors.requireCurrent(),since,until,memberId));} @GetMapping("/records") public ApiResponse<TrainingOverviewView> records(@RequestParam(required=false) LocalDate since,@RequestParam(required=false) LocalDate until,@RequestParam(required=false) Long memberId){return overview(since,until,memberId);} }
